        List<LocalDate> missingTempDates = new ArrayList<>();
        Map<LocalDate, TemperatureRecord> qualifying = new LinkedHashMap<>();
        for (LocalDate day : axis) {
            if (!turns.containsKey(day)) {
                missingTurnDates.add(day);
