@Test
void voidAndReleaseRaceIsConsistent() throws Exception {
    long batchId = newBatch("CONC-2");
    fillAllDays(batchId);
    // find the temp id of day 3 (only qualifying temp that day)
    Long tempId = jdbc.queryForObject("SELECT id FROM temperature_record WHERE batch_id=? AND temp_date='2026-01-03'", Long.class, batchId);
    run concurrently: thread A: service.voidTemperature(tempId, "race", null, null, null); thread B: service.release(batchId, "rel-race");
    collect outcomes (either may throw ApiException).
    boolean released = jdbc count release_record == 1;
    if (released) {
        // release committed before void: snapshot must reference tempId for 2026-01-03
